  it('passes a single stable composed ref to the child across re-renders', () => {
    const refIdentities = new Set<unknown>();
    let bump!: () => void;

    const Child = React.forwardRef<HTMLButtonElement>(function Child(_props, ref) {
      refIdentities.add(ref);
      return <button type="button" ref={ref} />;
  });

    function App() {
      const [, forceRender] = React.useReducer((c) => c + 1, 0);
      bump = forceRender;
      const forwardedRef = React.useRef<HTMLButtonElement>(null);
      return (
        <Slot ref={forwardedRef}>
          <Child />
        </Slot>
      );
    }

    render(<App />);
    act(() => bump());
    act(() => bump());
    expect(refIdentities.size).toBe(1);
  });

  it('passes the child ref unchanged when no forwardedRef is given', () => {
    const childRef = vi.fn();
    const refIdentities = new Set<unknown>();
    let bump!: () => void;

    function App() {
      const [, forceRender] = React.useReducer((c) => c + 1, 0);
      bump = forceRender;
      return (
        <Slot>
          <button type="button" ref={(node) => {
            refIdentities.add(node);
            childRef(node);
          }}>
            Click me
          </button>
        </Slot>
      );
    }

    render(<App />);
    act(() => bump());
    act(() => bump());
    // Slot has no forwardedRef, so it must pass the child's own ref straight through
    // (never wrapped in a composed ref), meaning it stays attached and is only called
    // once with the node.
    expect(refIdentities.size).toBe(1);
    expect(childRef).toHaveBeenCalledTimes(1);
    expect(childRef).toHaveBeenCalledWith(expect.any(HTMLButtonElement));
  });
});

